  const t=figma.createText();t.fontName={family:'Poppins',style:style||'Regular'};
  t.characters=chars;t.fontSize=size;t.fills=solid(color||'#FFFFFF');
  if(lh)t.lineHeight={value:lh,unit:'PIXELS'};
