function mkFrame(name,h,x){const f=figma.createFrame();f.name=name;f.resize(375,h);f.fills=[{type:'SOLID',color:BG}];f.clipsContent=true;f.x=x;f.y=4200;PAGE.appendChild(f);return f;}
function shell(f,h){const s=SB.createInstance();s.x=0;s.y=0;f.appendChild(s);const i=HI.createInstance();i.x=0;i.y=h-34;f.appendChild(i);}
function txt(str,size,style,color,w){const t=figma.createText();t.fontName={family:'Poppins',style:style};t.fontSize=size;t.characters=str;t.fills=[{type:'SOLID',color:color}];if(w){t.resize(w,t.height);t.textAutoResize='HEIGHT';}return t;}
function allText(n){const r=[],st=[n];while(st.length){const x=st.pop();if(x.type==='TEXT')r.push(x);if('children' in x)st.push(...x.children);}return r;}
function byName(n,nm){const st=[n];while(st.length){const x=st.pop();if(x.name===nm)return x;if('children' in x)st.push(...x.children);}return null;}
function titleHeader(inst,str){const ts=allText(inst).filter(t=>t.fontSize>=15);ts.sort((a,b)=>b.fontSize-a.fontSize);if(ts[0])ts[0].characters=str;return inst;}
function cover(inst,w,h,srcW,srcH){
  const s=Math.max(w/srcW,h/srcH);
  inst.resize(srcW*s,srcH*s);
  inst.x=(w-srcW*s)/2; inst.y=(h-srcH*s)/2;
}

