function findImg(n,path){
  if(!n) return;
  if(n.type==='RECTANGLE'||n.type==='FRAME'||n.type==='ELLIPSE'){
    const fl=n.fills;
    if(Array.isArray(fl)&&fl.length&&fl[0].type==='IMAGE'){
      out.push(path+n.name+' '+Math.round(n.width)+'x'+Math.round(n.height)+' hash='+fl[0].imageHash+' sm='+fl[0].scaleMode);
    }
  }
  if('children' in n) for(const c of n.children) findImg(c,path+n.name+'/');
}
